import Foundation
import SwiftData
import WCIWKit

/// Manages watchlist items and their airing status updates.
@MainActor
final class WatchlistManager: ObservableObject {
    /// Shared singleton instance.
    static let shared = WatchlistManager()

    /// Key for storing last refresh date in UserDefaults.
    private static let lastRefreshKey = "watchlistLastRefresh"

    /// The TMDB service for fetching airing info.
    private let tmdbService: TMDBService?

    /// UserDefaults instance for storing refresh date.
    private let defaults: UserDefaults

    /// Refresh policy for determining when to update airing info.
    let refreshPolicy: WatchlistRefreshPolicy

    /// Published property to trigger UI updates when refresh completes.
    @Published private(set) var isRefreshing = false

    /// Last refresh date, if any.
    var lastRefreshDate: Date? {
        get { defaults.object(forKey: Self.lastRefreshKey) as? Date }
        set { defaults.set(newValue, forKey: Self.lastRefreshKey) }
    }

    /// Creates a WatchlistManager with the given dependencies.
    /// - Parameters:
    ///   - tmdbService: The TMDB service to use for fetching airing info.
    ///   - defaults: UserDefaults instance for storing refresh date.
    ///   - refreshPolicy: Policy for refresh timing. Defaults to 24-hour interval.
    init(
        tmdbService: TMDBService? = nil,
        defaults: UserDefaults = .standard,
        refreshPolicy: WatchlistRefreshPolicy = WatchlistRefreshPolicy()
    ) {
        self.tmdbService = tmdbService ?? (try? TMDBService())
        self.defaults = defaults
        self.refreshPolicy = refreshPolicy
    }

    // MARK: - Add/Remove Operations

    /// Adds a media item (TV show or movie) to the watchlist.
    /// - Parameters:
    ///   - media: The media item to add.
    ///   - context: The model context for persistence.
    ///   - posterData: Cached poster image data for widget display.
    /// - Returns: The created WatchlistItem, or nil if already in watchlist.
    @discardableResult
    func addToWatchlist(_ media: Media, context: ModelContext, posterData: Data? = nil) async -> WatchlistItem? {
        // Check if already in watchlist
        if isInWatchlist(mediaId: media.id, context: context) {
            return nil
        }

        // For TV shows, fetch airing info
        var airingInfo: TVShowAiringInfo?
        if media.mediaType == .tv, let service = tmdbService {
            do {
                airingInfo = try await service.getTVShowAiringInfo(tvId: media.id)
            } catch {
                // Continue with nil airing info if fetch fails
            }
        }

        // Create and insert the item
        let item = WatchlistItem(from: media, airingInfo: airingInfo, posterData: posterData)
        context.insert(item)

        // Request notification permission if not yet determined
        await NotificationManager.shared.requestPermissionIfNeeded()

        return item
    }

    /// Removes a TV show from the watchlist.
    /// - Parameters:
    ///   - mediaId: The TMDB ID of the media to remove.
    ///   - context: The model context for persistence.
    /// - Returns: True if the item was removed, false if not found.
    @discardableResult
    func removeFromWatchlist(mediaId: Int, context: ModelContext) -> Bool {
        guard let item = fetchWatchlistItem(mediaId: mediaId, context: context) else {
            return false
        }
        context.delete(item)

        // Cascade: delete all watched episode records for this show
        let descriptor = FetchDescriptor<WatchedEpisode>(
            predicate: #Predicate { $0.mediaId == mediaId }
        )
        if let episodes = try? context.fetch(descriptor) {
            for episode in episodes {
                context.delete(episode)
            }
        }

        return true
    }

    /// Checks if a media item is in the watchlist.
    /// - Parameters:
    ///   - mediaId: The TMDB ID to check.
    ///   - context: The model context to query.
    /// - Returns: True if the item is in the watchlist.
    func isInWatchlist(mediaId: Int, context: ModelContext) -> Bool {
        fetchWatchlistItem(mediaId: mediaId, context: context) != nil
    }

    /// Fetches a specific watchlist item by media ID.
    /// - Parameters:
    ///   - mediaId: The TMDB ID to fetch.
    ///   - context: The model context to query.
    /// - Returns: The WatchlistItem if found, nil otherwise.
    func fetchWatchlistItem(mediaId: Int, context: ModelContext) -> WatchlistItem? {
        let descriptor = FetchDescriptor<WatchlistItem>(
            predicate: #Predicate { $0.mediaId == mediaId }
        )
        return try? context.fetch(descriptor).first
    }

    /// Fetches all watchlist items.
    /// - Parameter context: The model context to query.
    /// - Returns: Array of all WatchlistItems.
    func fetchAllWatchlistItems(context: ModelContext) -> [WatchlistItem] {
        let descriptor = FetchDescriptor<WatchlistItem>(
            sortBy: [SortDescriptor(\.dateAdded, order: .reverse)]
        )
        return (try? context.fetch(descriptor)) ?? []
    }

    // MARK: - Refresh Logic

    /// Determines if a refresh is needed based on the last refresh date.
    /// - Parameter currentDate: The current date to compare against. Defaults to now.
    /// - Returns: True if refresh is needed (more than 24 hours since last refresh).
    func needsRefresh(currentDate: Date = Date()) -> Bool {
        refreshPolicy.needsRefresh(lastRefreshDate: lastRefreshDate, currentDate: currentDate)
    }

    /// Refreshes airing info for all watchlist items if needed.
    /// - Parameters:
    ///   - context: The model context for persistence.
    ///   - force: If true, refreshes regardless of last refresh time.
    ///   - currentDate: The current date for refresh check. Defaults to now.
    func refreshIfNeeded(context: ModelContext, force: Bool = false, currentDate: Date = Date()) async {
        guard force || needsRefresh(currentDate: currentDate) else {
            return
        }

        await refreshAllAiringInfo(context: context)
        lastRefreshDate = currentDate
    }

    /// Refreshes airing info for all TV show watchlist items (movies are skipped).
    /// - Parameter context: The model context for persistence.
    func refreshAllAiringInfo(context: ModelContext) async {
        guard let service = tmdbService else { return }

        isRefreshing = true
        defer { isRefreshing = false }

        let items = fetchAllWatchlistItems(context: context)

        for item in items {
            // Only refresh TV shows, not movies
            guard item.isTVShow else { continue }

            do {
                let airingInfo = try await service.getTVShowAiringInfo(tvId: item.mediaId)
                item.update(with: airingInfo)
            } catch {
                // Keep existing data if refresh fails
            }
        }

        // Explicitly save changes to persist updated airing info
        try? context.save()

        // Reschedule episode notifications with updated airing data
        await NotificationManager.shared.rescheduleEpisodeNotifications(items: items)
    }

    /// Refreshes airing info for a single watchlist item (TV shows only).
    /// - Parameters:
    ///   - item: The item to refresh.
    ///   - context: The model context for persistence.
    func refreshAiringInfo(for item: WatchlistItem, context: ModelContext) async {
        // Only refresh TV shows, not movies
        guard item.isTVShow, let service = tmdbService else { return }

        do {
            let airingInfo = try await service.getTVShowAiringInfo(tvId: item.mediaId)
            item.update(with: airingInfo)
            try? context.save()
        } catch {
            // Keep existing data if refresh fails
        }
    }

    // MARK: - Episode Tracking

    /// Marks an episode as watched. Idempotent — no-op if already watched.
    func markEpisodeWatched(
        mediaId: Int,
        episodeId: Int,
        seasonNumber: Int,
        episodeNumber: Int,
        context: ModelContext
    ) {
        guard !isEpisodeWatched(episodeId: episodeId, context: context) else { return }

        let record = WatchedEpisode(
            episodeId: episodeId,
            mediaId: mediaId,
            seasonNumber: seasonNumber,
            episodeNumber: episodeNumber
        )
        context.insert(record)
    }

    /// Removes a watched episode record. No-op if not watched.
    func markEpisodeUnwatched(episodeId: Int, context: ModelContext) {
        let descriptor = FetchDescriptor<WatchedEpisode>(
            predicate: #Predicate { $0.episodeId == episodeId }
        )
        guard let record = try? context.fetch(descriptor).first else { return }
        context.delete(record)
    }

    /// Toggles an episode's watched state.
    /// - Returns: `true` if the episode is now watched, `false` if unwatched.
    @discardableResult
    func toggleEpisodeWatched(
        mediaId: Int,
        episodeId: Int,
        seasonNumber: Int,
        episodeNumber: Int,
        context: ModelContext
    ) -> Bool {
        if isEpisodeWatched(episodeId: episodeId, context: context) {
            markEpisodeUnwatched(episodeId: episodeId, context: context)
            return false
        } else {
            markEpisodeWatched(
                mediaId: mediaId,
                episodeId: episodeId,
                seasonNumber: seasonNumber,
                episodeNumber: episodeNumber,
                context: context
            )
            return true
        }
    }

    /// Checks whether a specific episode is marked as watched.
    func isEpisodeWatched(episodeId: Int, context: ModelContext) -> Bool {
        let descriptor = FetchDescriptor<WatchedEpisode>(
            predicate: #Predicate { $0.episodeId == episodeId }
        )
        let count = (try? context.fetchCount(descriptor)) ?? 0
        return count > 0
    }

    /// Returns all watched episode records for a given show.
    func watchedEpisodes(for mediaId: Int, context: ModelContext) -> [WatchedEpisode] {
        let descriptor = FetchDescriptor<WatchedEpisode>(
            predicate: #Predicate { $0.mediaId == mediaId }
        )
        return (try? context.fetch(descriptor)) ?? []
    }

    /// Returns the count of watched episodes for a specific season of a show.
    func watchedEpisodeCount(for mediaId: Int, seasonNumber: Int, context: ModelContext) -> Int {
        let descriptor = FetchDescriptor<WatchedEpisode>(
            predicate: #Predicate { $0.mediaId == mediaId && $0.seasonNumber == seasonNumber }
        )
        return (try? context.fetchCount(descriptor)) ?? 0
    }

    /// Batch marks all episodes in a season as watched.
    func markSeasonWatched(mediaId: Int, episodes: [Episode], context: ModelContext) {
        for episode in episodes {
            markEpisodeWatched(
                mediaId: mediaId,
                episodeId: episode.id,
                seasonNumber: episode.seasonNumber,
                episodeNumber: episode.episodeNumber,
                context: context
            )
        }
    }

    /// Batch removes all watched episode records for a specific season of a show.
    func markSeasonUnwatched(mediaId: Int, seasonNumber: Int, context: ModelContext) {
        let descriptor = FetchDescriptor<WatchedEpisode>(
            predicate: #Predicate { $0.mediaId == mediaId && $0.seasonNumber == seasonNumber }
        )
        guard let episodes = try? context.fetch(descriptor) else { return }
        for episode in episodes {
            context.delete(episode)
        }
    }

}

import Foundation
import UserNotifications
import SwiftData
import WCIWKit

/// Manages local notification scheduling, permissions, and badge state.
@MainActor
final class NotificationManager: ObservableObject {
    static let shared = NotificationManager()

    /// Whether the user has granted notification permission.
    @Published private(set) var isAuthorized = false

    /// Media to navigate to when a notification is tapped.
    @Published var pendingMediaId: Int?
    @Published var pendingMediaType: MediaType?

    /// UserDefaults key for user's notification toggle.
    private static let notificationsEnabledKey = "notificationsEnabled"

    /// UserDefaults key for the last time the user opened the app.
    private static let lastOpenedDateKey = "lastOpenedDate"

    /// The last time the user brought the app to the foreground.
    /// Used as the baseline for badge count calculation. Defaults to `.distantPast`
    /// so that first-launch users see badges for all pending notifications.
    var lastOpenedDate: Date {
        get {
            let interval = UserDefaults.standard.double(forKey: Self.lastOpenedDateKey)
            return interval > 0 ? Date(timeIntervalSince1970: interval) : .distantPast
        }
        set {
            UserDefaults.standard.set(newValue.timeIntervalSince1970, forKey: Self.lastOpenedDateKey)
        }
    }

    /// Whether the user has enabled notifications in app settings.
    var notificationsEnabled: Bool {
        get { UserDefaults.standard.bool(forKey: Self.notificationsEnabledKey) }
        set { UserDefaults.standard.set(newValue, forKey: Self.notificationsEnabledKey) }
    }

    private init() {
        Task { await refreshAuthorizationStatus() }
    }

    // MARK: - Permission

    /// Requests notification permission from the user.
    func requestPermission() async -> Bool {
        do {
            let granted = try await UNUserNotificationCenter.current()
                .requestAuthorization(options: [.alert, .badge, .sound])
            isAuthorized = granted
            if granted {
                notificationsEnabled = true
            }
            return granted
        } catch {
            return false
        }
    }

    /// Requests permission if not yet determined. Called after first watchlist save.
    func requestPermissionIfNeeded() async {
        let settings = await UNUserNotificationCenter.current().notificationSettings()
        guard settings.authorizationStatus == .notDetermined else { return }
        _ = await requestPermission()
    }

    /// Refreshes the current authorization status.
    func refreshAuthorizationStatus() async {
        let settings = await UNUserNotificationCenter.current().notificationSettings()
        isAuthorized = settings.authorizationStatus == .authorized
    }

    /// Whether notifications should be active (authorized + enabled).
    func shouldScheduleNotifications() -> Bool {
        isAuthorized && notificationsEnabled
    }

    // MARK: - Episode Notifications

    /// Reschedules episode notifications for all TV shows with upcoming episodes.
    /// Badge values are based on episodes airing after `lastOpenedDate`, not on
    /// Notification Center state. This prevents badge inflation across scheduling runs.
    func rescheduleEpisodeNotifications(items: [WatchlistItem]) async {
        guard shouldScheduleNotifications() else { return }

        let center = UNUserNotificationCenter.current()

        // Remove all existing episode notifications
        let pendingRequests = await center.pendingNotificationRequests()
        let episodeIds = pendingRequests
            .filter { $0.identifier.hasPrefix("episode-") }
            .map(\.identifier)
        center.removePendingNotificationRequests(withIdentifiers: episodeIds)

        // Build content for all eligible episodes
        var contentItems: [(content: NotificationContent, airDate: Date)] = []
        for item in items where item.isTVShow {
            guard let airDate = item.nextEpisodeDate else { continue }

            guard let content = NotificationContentBuilder.episodeNotification(
                mediaId: item.mediaId,
                title: item.title,
                seasonNumber: item.nextSeasonNumber,
                episodeNumber: item.nextEpisodeNumber,
                episodeName: item.nextEpisodeName,
                airDate: airDate
            ) else { continue }

            contentItems.append((content, airDate))
        }

        // Schedule chronologically so badge values (1, 2, 3...) match air order
        let sortedItems = contentItems.sorted { $0.airDate < $1.airDate }
        var badgeOffset = 0
        for (content, airDate) in sortedItems {
            if airDate > lastOpenedDate {
                badgeOffset += 1
                await scheduleNotification(content, badgeCount: badgeOffset)
            } else {
                await scheduleNotification(content)
            }
        }
    }

    // MARK: - Movie Availability Notifications

    /// Creates a notification for a movie that is now available to stream.
    /// Badge count accounts for any pending episode notifications that will fire
    /// after `lastOpenedDate`, plus this movie notification.
    func notifyMovieAvailable(item: WatchlistItem, serviceName: String) async {
        guard shouldScheduleNotifications() else { return }

        let content = NotificationContentBuilder.movieAvailableNotification(
            mediaId: item.mediaId,
            title: item.title,
            serviceName: serviceName
        )

        // Count pending episode notifications that will fire after lastOpenedDate
        let center = UNUserNotificationCenter.current()
        let pendingRequests = await center.pendingNotificationRequests()
        let episodeCount = pendingRequests
            .filter { $0.identifier.hasPrefix("episode-") }
            .compactMap { $0.trigger as? UNCalendarNotificationTrigger }
            .compactMap { (trigger: UNCalendarNotificationTrigger) -> Date? in
                Calendar.current.date(from: trigger.dateComponents)
            }
            .filter { $0 > lastOpenedDate }
            .count

        await scheduleNotification(content, badgeCount: episodeCount + 1)
    }

    // MARK: - Scheduling

    /// Schedules a local notification from NotificationContent metadata.
    /// - Parameters:
    ///   - content: The notification metadata to schedule.
    ///   - badgeCount: The badge count to display. When nil, the notification
    ///     does not modify the app badge (used for episodes before lastOpenedDate).
    private func scheduleNotification(_ content: NotificationContent, badgeCount: Int? = nil) async {
        let notificationContent = UNMutableNotificationContent()
        notificationContent.title = content.title
        notificationContent.body = content.body
        notificationContent.categoryIdentifier = content.categoryIdentifier
        notificationContent.threadIdentifier = content.threadIdentifier
        notificationContent.sound = .default
        notificationContent.userInfo = [
            "mediaId": content.mediaId,
            "mediaType": content.mediaType
        ]

        if let badgeCount {
            notificationContent.badge = NSNumber(value: badgeCount)
        }

        // Create trigger
        let trigger: UNNotificationTrigger?
        if let triggerDate = content.triggerDate {
            let components = Calendar.current.dateComponents(
                [.year, .month, .day, .hour, .minute],
                from: triggerDate
            )
            trigger = UNCalendarNotificationTrigger(dateMatching: components, repeats: false)
        } else {
            // Immediate delivery (for movie availability)
            trigger = nil
        }

        let request = UNNotificationRequest(
            identifier: content.identifier,
            content: notificationContent,
            trigger: trigger
        )

        do {
            try await UNUserNotificationCenter.current().add(request)
        } catch {
            // Notification scheduling failed — non-fatal
        }
    }

    // MARK: - Badge Management

    /// Clears the app badge and records the current time as `lastOpenedDate`.
    /// Called when the app enters the foreground. Notification Center entries
    /// are not removed — the user manages those independently.
    func clearBadge() async {
        lastOpenedDate = Date()
        try? await UNUserNotificationCenter.current().setBadgeCount(0)
    }

    // MARK: - Cancellation

    /// Cancels all pending notifications. Called when premium lapses.
    func cancelAllNotifications() {
        UNUserNotificationCenter.current().removeAllPendingNotificationRequests()
        Task { await clearBadge() }
    }

    /// Cancels notifications for a specific media item.
    func cancelNotifications(for mediaId: Int) {
        let identifiers = ["episode-\(mediaId)", "streaming-\(mediaId)"]
        UNUserNotificationCenter.current().removePendingNotificationRequests(withIdentifiers: identifiers)
    }

    // MARK: - Notification Response Handling

    /// Handles a notification tap with extracted userInfo values.
    func handleNotificationTap(mediaId: Int?, mediaTypeRaw: String?) {
        guard let mediaId,
              let mediaTypeRaw,
              let mediaType = MediaType(rawValue: mediaTypeRaw) else { return }
        pendingMediaId = mediaId
        pendingMediaType = mediaType
    }

    // MARK: - Notification Categories

    // MARK: - Debug Helpers

    #if DEBUG
    /// Ensures notification permission is granted, requesting if needed.
    /// Returns a status message describing the result.
    func ensureDebugPermission() async -> String? {
        let settings = await UNUserNotificationCenter.current().notificationSettings()
        switch settings.authorizationStatus {
        case .authorized:
            return nil
        case .notDetermined:
            let granted = await requestPermission()
            return granted ? nil : "Permission denied"
        case .denied:
            return "Notifications denied in Settings"
        default:
            return "Notification permission unavailable"
        }
    }

    /// Schedules a test episode notification that fires in 5 seconds.
    /// Uses Breaking Bad S5 E16 "Felina" (TMDB ID 1396).
    func scheduleTestEpisodeNotification() async -> String {
        if let error = await ensureDebugPermission() {
            return error
        }

        let content = UNMutableNotificationContent()
        content.title = "Breaking Bad"
        content.body = "Felina (S5 E16) airs today"
        content.categoryIdentifier = NotificationCategory.newEpisode.rawValue
        content.threadIdentifier = "episode-1396"
        content.sound = .default
        content.badge = NSNumber(value: 1)
        content.userInfo = ["mediaId": 1396, "mediaType": "tv"]

        let trigger = UNTimeIntervalNotificationTrigger(timeInterval: 5, repeats: false)
        let request = UNNotificationRequest(identifier: "debug-episode", content: content, trigger: trigger)
        do {
            try await UNUserNotificationCenter.current().add(request)
            return "Episode notification scheduled (5 sec)"
        } catch {
            return "Failed: \(error.localizedDescription)"
        }
    }

    /// Schedules a test movie notification that fires in 5 seconds.
    /// Uses Fight Club (TMDB ID 550).
    func scheduleTestMovieNotification() async -> String {
        if let error = await ensureDebugPermission() {
            return error
        }

        let content = UNMutableNotificationContent()
        content.title = "Fight Club"
        content.body = "Now streaming on Netflix"
        content.categoryIdentifier = NotificationCategory.nowStreaming.rawValue
        content.threadIdentifier = "streaming-550"
        content.sound = .default
        content.badge = NSNumber(value: 1)
        content.userInfo = ["mediaId": 550, "mediaType": "movie"]

        let trigger = UNTimeIntervalNotificationTrigger(timeInterval: 5, repeats: false)
        let request = UNNotificationRequest(identifier: "debug-movie", content: content, trigger: trigger)
        do {
            try await UNUserNotificationCenter.current().add(request)
            return "Movie notification scheduled (5 sec)"
        } catch {
            return "Failed: \(error.localizedDescription)"
        }
    }
    #endif

    // MARK: - Notification Categories

    /// Registers notification categories with the system.
    static func registerCategories() {
        let episodeCategory = UNNotificationCategory(
            identifier: NotificationCategory.newEpisode.rawValue,
            actions: [],
            intentIdentifiers: []
        )
        let streamingCategory = UNNotificationCategory(
            identifier: NotificationCategory.nowStreaming.rawValue,
            actions: [],
            intentIdentifiers: []
        )
        UNUserNotificationCenter.current().setNotificationCategories([
            episodeCategory,
            streamingCategory
        ])
    }
}

